let fileSystem = new Map();

class FileMock {
    constructor(path, mode, size) {
        this.path = path;
        this.mode = mode;
        this.size = size || 0;
        if (mode === "w+" || mode === "r+") {
            if (!fileSystem.has(path)) {
                fileSystem.set(path, new Uint8Array(0));
            }
        }
    }

    write(arrayBuffer, offset) {
        const bytes = new Uint8Array(arrayBuffer);
        const currentData = fileSystem.get(this.path) || new Uint8Array(0);
        
        let newData;
        if (offset + bytes.length > currentData.length) {
            newData = new Uint8Array(offset + bytes.length);
            newData.set(currentData);
        } else {
            newData = new Uint8Array(currentData);
        }
        newData.set(bytes, offset);
        fileSystem.set(this.path, newData);
        this.size = newData.length;
        return bytes.length;
    }

    read(size, offset) {
        const data = fileSystem.get(this.path);
        if (!data) return new ArrayBuffer(0);
        const slice = data.slice(offset, offset + size);
        return slice.buffer;
    }

    status() {
        const data = fileSystem.get(this.path);
        return {
            size: data ? data.length : 0
        };
    }

    close() {
        // No-op
    }
}

const device = {
    files: {
        openFile({ path, mode, size }) {
            if (mode !== "w+" && mode !== "r+" && !fileSystem.has(path)) {
                throw new Error("File not found: " + path);
            }
            return new FileMock(path, mode, size);
        },
        delete(path) {
            fileSystem.delete(path);
        }
    }
};

export default device;

export function _reset() {
    fileSystem = new Map();
}

export function _getFilesystem() {
    return fileSystem;
}
